data.alerts.yml:
groups:
  - name: pilot
    rules:
      - alert: PilotCollectorUnavailable
        expr: up{job="pilot"} == 0 or pilot_collection_success == 0
        for: 2m
        labels: {severity: warning}
        annotations: {summary: 'Pilot metadata collection is unavailable'}
      - alert: PilotControllerUnavailable
        expr: pilot_controller_up == 0
        for: 2m
        labels: {severity: critical}
        annotations: {summary: 'An existing pilot controller has stopped'}
      - alert: PilotControllerRestarting
        expr: increase(pilot_controller_restarts_total[10m]) > 2
        labels: {severity: warning}
        annotations: {summary: 'A pilot controller is repeatedly restarting'}
      - alert: PilotWorkerUnavailable
        expr: (pilot_worker_desired == 1) and on(slot) (pilot_worker_paused == 0) and on(slot) (pilot_worker_ready == 0)
        for: 15m
        labels: {severity: warning}
        annotations: {summary: 'Requested unpaused worker has not become Ready in 15 minutes'}
      - alert: PilotSwapping
        expr: rate(pilot_host_swap_pages_total[5m]) > 0
        for: 5m
        labels: {severity: warning}
        annotations: {summary: 'Laptop is sustaining swap activity; stop adding services'}
      - alert: PilotMemoryLow
        expr: pilot_host_memory_bytes{kind="MemAvailable"} < 536870912
        for: 5m
        labels: {severity: warning}
        annotations: {summary: 'Laptop available memory is below the 512 MiB reserve'}
      - alert: PilotDiskBudget
        expr: (kubelet_volume_stats_available_bytes{namespace="pilot-monitoring"} / kubelet_volume_stats_capacity_bytes{namespace="pilot-monitoring"}) < 0.2 or pilot_host_disk_free_bytes < 5368709120
        for: 2m
        labels: {severity: warning}
        annotations: {summary: 'Pilot log budget or laptop disk reserve needs attention'}
      - alert: PilotCollectionStale
        expr: time() - pilot_collection_timestamp_seconds > 120
        for: 1m
        labels: {severity: warning}
        annotations: {summary: 'Pilot metadata collection stopped updating'}
      - alert: PilotMonitoringUnavailable
        expr: up{job=~"loki|alloy|prometheus|pilot"} == 0
        for: 2m
        labels: {severity: warning}
        annotations: {summary: 'A pilot monitoring service has stopped; check disk budget and journal'}
      - alert: PilotKubernetesControllerUnavailable
        expr: pilot_kubernetes_controller_available < 1
        for: 2m
        labels: {severity: warning}
        annotations: {summary: 'A named pilot Kubernetes controller is unavailable'}

